message.content:
{
  "definition_simple": "活気づく、興奮が高まる",
  "definition_standard": "雰囲気や気分が高まり、活気にあふれるようになる。また、興奮や熱気が高まる。",
  "pos": "五段自動詞",
  "semantic_class": "action",
  "sentences": [
    {
      "sentence": "パーティーがとても盛り上がった。",
      "tier": "T1"
    },
    {
      "sentence": "試合が盛り上がってきた。",
      "tier": "T2"
    },
    {
      "sentence": "彼のスピーチで会場が盛り上がった。",
      "tier": "T2"
    },
    {
      "sentence": "音楽が流れると、みんなの気分が盛り上がる。",
      "tier": "T3"
    },
    {
      "sentence": "イベントの終盤に盛り上がりを見せた。",
      "tier": "T3"
    },
    {
      "sentence": "新しい企画で社内の雰囲気が盛り上がっている。",
      "tier": "T4"
    },
    {
      "sentence": "観客の歓声がますます盛り上がっていく。",
      "tier": "T4"
    },
    {
      "sentence": "政治的な議論が夜遅くまで盛り上がった。",
      "tier": "T5"
    },
    {
      "sentence": "地元の祭りは毎年見事に盛り上がることで知られている。",
      "tier": "T5"
    },
    {
      "sentence": "経済指標の改善により、市場心理が再び盛り上がり始めた。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [
    {
      "form": "盛り上がった",
      "label": "過去形"
    },
    {
      "form": "盛り上がって",
      "label": "テ形"
    }
  ],
  "morphology_wrong_forms": [
    {
      "wrong_form": "盛り上がりた",
      "explanation": "「た」形を作る際に「り」を残したまま「た」を付けてしまう誤り。正しくは「盛り上がった」。"
    },
    {
      "wrong_form": "盛り上がったて",
      "explanation": "テ形に過去の「た」を重ねてしまった誤り。正しくは「盛り上がって」。"
    },
    {
      "wrong_form": "盛り上がらった",
      "explanation": "五段動詞「盛り上がる」の連用形は「盛り上がり」であり、「ら」を挿入するのは誤り。正しくは「盛り上がった」。"
    },
    {
      "wrong_form": "盛り上がいて",
      "explanation": "「上がって」の部分を「上がいて」と誤って変化させた。正しくは「盛り上がって」。"
    },
    {
      "wrong_form": "盛り上がりて",
      "explanation": "テ形は連用形＋「て」だが、五段活用では音便が起こるため「盛り上がって」となる。"
    },
    {
      "wrong_form": "盛り上がて",
      "explanation": "「上がって」の促音を落とした誤り。正しくは「盛り上がって」。"
    }
  ],
  "primary_collocate": "会場",
  "collocation_distractors": [
    {
      "word": "楽しい",
      "explanation": "「楽しい」は形容詞であり、「盛り上がる」と共起するのは自然ですが、直接のコロケーションではなく、主に修飾関係で用いられます。"
    },
    {
      "word": "興奮",
      "explanation": "「興奮」は名詞であり、「盛り上がる」と意味は近いですが、コロケーションとしては「興奮する」が対応します。"
    },
    {
      "word": "熱気",
      "explanation": "「熱気」は名詞で、状況を表しますが「熱気が盛り上がる」という形は稀で、通常は「熱気で盛り上がる」のように用いられます。"
    }
  ],
  "collocation_wrong_collocate": "意見",
  "collocation_wrong_explanation": "「意見が盛り上がる」は、意見が高まるという意味で使われることがありますが、標準的な日本語では「議論が盛り上がる」が正しく、「意見」そのものが盛り上がるとは言いません。",
  "cloze_distractors": [
    {
      "sentence": "彼のスピーチで会場が___。",
      "correct_answer": "盛り上がった",
      "distractors": [
        {
          "word": "沸いた",
          "explanation": "「沸く」は「盛り上がる」と似た意味だが、物理的な沸騰や感情の沸騰に使われることが多く、この文脈では「盛り上がる」の方が自然。"
        },
        {
          "word": "冷めた",
          "explanation": "「冷める」は興奮が収まる意味であり、文脈と反対の意味になる。"
        },
        {
          "word": "始まった",
          "explanation": "「始まる」はイベントの開始を示し、盛り上がりの状態を表さない。"
        }
      ]
    },
    {
      "sentence": "音楽が流れると、みんなの気分が___。",
      "correct_answer": "盛り上がる",
      "distractors": [
        {
          "word": "上がる",
          "explanation": "「気分が上がる」は口語で使われるが、より広い意味の「盛り上がる」とは異なり、特定の状況に限定される。"
        },
        {
          "word": "下がる",
          "explanation": "「下がる」は逆の意味。"
        },
        {
          "word": "落ち着く",
          "explanation": "「落ち着く」は興奮が静まる意味で、文脈に合わない。"
        }
      ]
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼女は盛り上がることを楽しんだ。",
      "reason": "「盛り上がる」は自動詞であり、目的語を取れない。この文では「盛り上がること」を目的語として扱っているが、動詞の使用法として不適切。正しくは「彼女は盛り上がったことを楽しんだ」など。"
    },
    {
      "sentence": "雨が盛り上がっている。",
      "reason": "「盛り上がる」は人の感情や雰囲気に用いるのが通常で、雨のような自然現象には使わない。正しくは「雨が強くなっている」など。"
    },
    {
      "sentence": "その本は内容が盛り上がっている。",
      "reason": "「内容が盛り上がる」は比喩的に使われることはあるが、標準的ではなく、特に書籍の内容には「盛り上がる」よりも「面白い」「充実している」などが適切。主語と動詞の結びつきが不自然。"
    }
  ],
  "spot_incorrect": {
    "sentence": "会場を盛り上がった。",
    "error_description": "格助詞「を」の誤用。「盛り上がる」は自動詞なので主格「が」を使うべき。",
    "corrected_version": "会場が盛り上がった。"
  },
  "word_family_forms": [
    "盛り上がり（名詞）",
    "盛り上げる（他動詞）"
  ],
  "word_family_fake_forms": [
    {
      "form": "盛り上がるさ",
      "explanation": "名詞化接尾辞「さ」を付けた形だが、実際の日本語には存在しない。"
    },
    {
      "form": "盛り上がり性",
      "explanation": "「性」を付けた抽象名詞だが、標準的な語彙ではない。"
    },
    {
      "form": "盛り上がむ",
      "explanation": "五段動詞「盛り上がる」の活用を模したが、正しくは「盛り上がる」のみ。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "賑わう",
      "type": "synonym",
      "explanation": "「賑わう」は人が多く活気がある状態を表し、この意味で「盛り上がる」と同義。"
    },
    {
      "word": "活気づく",
      "type": "synonym",
      "explanation": "「活気づく」は活気が生まれることを表し、「盛り上がる」とほぼ同じ意味。"
    },
    {
      "word": "沸く",
      "type": "synonym",
      "explanation": "「沸く」は興奮や熱気が高まる意味で、特に観客や会場に使われる。"
    },
    {
      "word": "しらける",
      "type": "antonym",
      "explanation": "「しらける」は興醒めして冷めることを表し、「盛り上がる」の反対。"
    }
  ],
  "particle_candidates": {
    "sentence": "彼の冗談で、会場___盛り上がった。",
    "candidates": [
      {
        "particle": "が",
        "correct": true,
        "explanation": "主格を示し、会場が主語となるので正しい。"
      },
      {
        "particle": "を",
        "correct": false,
        "explanation": "「盛り上がる」は自動詞のため目的語を取らず、「を」は誤り。"
      },
      {
        "particle": "に",
        "correct": false,
        "explanation": "「に」は場所や時間を示すが、ここでは主語が必要であり不適切。"
      },
      {
        "particle": "で",
        "correct": false,
        "explanation": "「で」は原因・手段を示すが、「会場で」は「会場において」となり、この文では主語が欠ける。正しくは「会場が」が必要。"
      }
    ]
  }
}
